"""Naive reference implementation of the published contract (small inputs only).

Independent of the project: everything expands to plain bytes and the replay is
an explicit state machine instead of coroutines.
"""
import ast
import hashlib

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
TOKEN_CHARS = set(b"!#$%&'*+.^_`|~0123456789abcdefghijklmnopqrstuvwxyz"
                  b"ABCDEFGHIJKLMNOPQRSTUVWXYZ-")


def fp(data):
    h = 0
    for value in data:
        h = (h * 257 + value + 1) & MASK
    return {'n': len(data), 'h': '%016x' % h}


def evaluate(source, env):
    tree = ast.parse(source, mode='eval')

    def go(node):
        if isinstance(node, ast.Constant):
            value = node.value
            if isinstance(value, bool) or value is None:
                raise ValueError
            if isinstance(value, bytes):
                return value
            if isinstance(value, str):
                return value.encode('utf-8')
            if isinstance(value, int):
                if not 0 <= value <= MAX:
                    raise ValueError
                return value
            raise ValueError
        if isinstance(node, ast.Name):
            return env[node.id]
        if isinstance(node, ast.BinOp):
            left = go(node.left)
            right = go(node.right)
            if isinstance(node.op, ast.Add):
                if not isinstance(left, bytes) or not isinstance(right, bytes):
                    raise ValueError
                return left + right
            if isinstance(node.op, ast.Mult):
                if isinstance(left, bytes) and isinstance(right, int):
                    return left * right
                if isinstance(left, int) and isinstance(right, bytes):
                    return right * left
                raise ValueError
            raise ValueError
        if isinstance(node, ast.Subscript):
            base = go(node.value)
            if not isinstance(base, bytes):
                raise ValueError
            index = node.slice
            if not isinstance(index, ast.Slice) or index.step is not None:
                raise ValueError

            def endpoint(part):
                if part is None:
                    return None
                if not isinstance(part, ast.Constant) or isinstance(part.value, bool) \
                        or not isinstance(part.value, int):
                    raise ValueError
                return part.value
            low = endpoint(index.lower)
            high = endpoint(index.upper)
            low = 0 if low is None else low
            high = len(base) if high is None else high
            if not 0 <= low <= high <= len(base):
                raise ValueError
            return base[low:high]
        raise ValueError
    result = go(tree.body)
    if not isinstance(result, bytes):
        raise ValueError
    return result


class Ref:
    def __init__(self, document):
        self.doc = document
        self.seed = document['seed']
        self.env = {}
        for name, source in document['definitions']:
            self.env[name] = evaluate(source, self.env)

    def template(self, value, coordinate):
        if value.startswith('{{') and value.endswith('}}'):
            return evaluate(value[2:-2].strip(), self.env)
        if '<<random_string>>' not in value:
            return value.encode('utf-8')
        pieces = value.split('<<random_string>>')
        out = []
        for index, piece in enumerate(pieces):
            out.append(piece.encode('utf-8'))
            if index + 1 < len(pieces):
                source = '%s/%s/%d' % (self.seed, coordinate, index)
                out.append(hashlib.sha256(source.encode()).hexdigest()[:20].encode())
        return b''.join(out)

    # ------------------------------------------------------------ receipts #
    def action(self, at, stream, kind, content, end):
        head = at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode()
        if kind in 'Hh':
            body = len(content).to_bytes(8, 'big')
            for name, value in content:
                body += len(name).to_bytes(8, 'big') + name
                body += len(value).to_bytes(8, 'big') + value
        else:
            body = len(content).to_bytes(8, 'big') + content
        return head + body + bytes([1 if end else 0])

    def replay(self):
        doc = self.doc
        timeout = doc['timeout_ms']
        states = []
        for index, case in enumerate(doc['cases']):
            frames = []
            for position, frame in enumerate(case['frames']):
                kind = frame['Type']
                coordinate = 'case/%d/frame/%d' % (index, position)
                if kind == 'sleep':
                    frames.append(('sleep', frame['Time_to_Stop'], False))
                elif kind == 'headers':
                    if 'headers_kv' in frame:
                        rows = list(frame['headers_kv'].items())
                    else:
                        rows = [tuple(pair) for pair in frame['data_to_transfered']]
                    frames.append(('headers',
                                   [(self.template(n, coordinate + '/h/%d/n' % k),
                                     self.template(v, coordinate + '/h/%d/v' % k))
                                    for k, (n, v) in enumerate(rows)],
                                   frame.get('End_Stream', False)))
                else:
                    frames.append((kind,
                                   self.template(frame['data_to_transfered'],
                                                 coordinate + '/data'),
                                   frame.get('End_Stream', True)))
            states.append({'case': case, 'index': index, 'stream': 4 * index,
                           'frames': frames, 'pc': 0, 'phase': 'init', 'closed': False,
                           'end': False, 'events': [], 'sent': b'', 'received': b'',
                           'body': b'', 'frames_count': 0, 'request_frames': 0,
                           'payload': 0, 'state': None, 'at': None})
        events = []
        for index, record in enumerate(doc['events']):
            row = dict(record)
            if row['kind'] == 'headers':
                row['fields'] = [(self.template(n, 'event/%d/h/%d/n' % (index, k)),
                                  self.template(v, 'event/%d/h/%d/v' % (index, k)))
                                 for k, (n, v) in enumerate(row['fields'])]
            elif row['kind'] == 'data':
                row['data'] = self.template(row['data'], 'event/%d/data' % index)
            events.append(row)
        by_stream = {state['stream']: state for state in states}
        queue = []
        for index in range(len(states)):
            queue.append([0, -1, index, ('start', index)])
        for index, row in enumerate(events):
            queue.append([row['at'], 0, index, ('external', index)])
        closed = False
        while queue:
            queue.sort(key=lambda row: (row[0], row[1], row[2]))
            now, _, _, what = queue.pop(0)
            flavour = what[0]
            if flavour in ('start', 'resume'):
                state = states[what[1]]
                if state['state'] is not None:
                    continue
                if closed:
                    state['state'] = 'closed'
                    state['at'] = now
                    continue
                state['phase'] = 'send'
                finished = True
                while state['pc'] < len(state['frames']):
                    frame = state['frames'][state['pc']]
                    if frame[0] == 'sleep':
                        state['pc'] += 1
                        queue.append([now + frame[1], 1, state['index'],
                                      ('resume', state['index'])])
                        state['phase'] = 'paused'
                        finished = False
                        break
                    if state['closed']:
                        state['state'] = 'send_error'
                        state['at'] = now
                        finished = False
                        break
                    kind, content, end = frame
                    if kind == 'headers':
                        state['sent'] += self.action(now, state['stream'], 'H', content, end)
                        state['payload'] += sum(len(n) + len(v) for n, v in content)
                        state['request_frames'] += 1
                    elif kind == 'data':
                        state['sent'] += self.action(now, state['stream'], 'D', content, end)
                        state['payload'] += len(content)
                        state['request_frames'] += 1
                    else:
                        state['sent'] += self.action(now, state['stream'], 'G', content, False)
                        state['payload'] += len(content)
                    state['frames_count'] += 1
                    if kind != 'datagram' and end:
                        state['closed'] = True
                    state['pc'] += 1
                if finished:
                    if state['end']:
                        state['state'] = 'ok'
                        state['at'] = now
                    else:
                        state['phase'] = 'wait'
                        queue.append([now + timeout, 2, state['index'],
                                      ('timeout', state['index'])])
                continue
            if flavour == 'timeout':
                state = states[what[1]]
                if state['state'] is None and state['phase'] == 'wait':
                    state['state'] = 'timeout'
                    state['at'] = now
                continue
            row = events[what[1]]
            if row['kind'] == 'close':
                closed = True
                for state in states:
                    if state['state'] is None:
                        state['state'] = 'closed'
                        state['at'] = now
                continue
            state = by_stream.get(row['stream'])
            if state is None or state['state'] is not None or state['end']:
                continue
            content = row['fields'] if row['kind'] == 'headers' else row['data']
            lower = 'h' if row['kind'] == 'headers' else 'd'
            state['received'] += self.action(now, state['stream'], lower, content, row['end'])
            state['events'].append(row)
            if row['kind'] == 'data':
                state['body'] += row['data']
            if row['end']:
                state['end'] = True
                if state['phase'] == 'wait':
                    state['state'] = 'ok'
                    state['at'] = now
        rows = []
        for state in states:
            rows.append({'name': state['case']['name'], 'stream': state['stream'],
                         'state': state['state'], 'at': state['at'],
                         'frames': state['frames_count'],
                         'request_frames': state['request_frames'],
                         'payload_bytes': state['payload'],
                         'sent': fp(state['sent']), 'received': fp(state['received']),
                         'response_frames': len(state['events']),
                         'response_body': fp(state['body']),
                         'origin_count': 0, 'flags': []})
        return rows


def solve(document):
    ref = Ref(document)
    channels = []
    for index, channel in enumerate(document['channels']):
        parts = []
        for position, part in enumerate(channel['parts']):
            parts.append({'case': part['case'],
                          'data': ref.template(part['data'],
                                               'channel/%d/part/%d/data' % (index, position))})
        channels.append({'name': channel['name'], 'parts': parts})
    cases = ref.replay()
    import capture_ref
    parsed = [capture_ref.parse(channel) for channel in channels]
    expects = {case['name']: case['expect'] for case in document['cases']}
    request_frames = {row['name']: row['request_frames'] for row in cases}
    ordered = []
    for row in parsed:
        ordered.extend(row['requests'])
    counts = {}
    for record in ordered:
        owner = record['owner']
        flags = []
        if owner is None:
            flags.append('unattributed')
        if len(record['owners']) > 1:
            flags.append('mixed_owner')
        hosts = record['_hosts']
        if not hosts:
            flags.append('missing_host')
        elif len(hosts) > 1:
            flags.append('multiple_host')
        if owner is not None:
            expect = expects[owner]
            if record['_method'] != expect['method'].encode() or \
                    record['_target'] != expect['target'].encode() or \
                    len(hosts) != 1 or hosts[0].lower() != expect['host'].encode().lower():
                flags.append('identity')
            counts[owner] = counts.get(owner, 0) + 1
            if counts[owner] > 1:
                flags.append('extra')
            if request_frames.get(owner, 1) == 0:
                flags.append('unsent')
        record['flags'] = sorted(flags)
    owned = {}
    origin = {}
    for record in ordered:
        owner = record['owner']
        if owner is None:
            continue
        origin[owner] = origin.get(owner, 0) + 1
        bucket = owned.setdefault(owner, set())
        if 'identity' in record['flags']:
            bucket.add('identity')
        if 'mixed_owner' in record['flags']:
            bucket.add('mixed_origin')
    for row in cases:
        name = row['name']
        count = origin.get(name, 0)
        row['origin_count'] = count
        flags = set(owned.get(name, ()))
        if row['request_frames'] > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and row['request_frames'] == 0:
            flags.add('unsent_origin')
        row['flags'] = sorted(flags)
    for row in parsed:
        for record in row['requests']:
            record.pop('_hosts')
            record.pop('_method')
            record.pop('_target')
    return {'cases': cases, 'channels': parsed}
